import subprocess
import sys
import tempfile

files = ['app.py', 'config.py', 'formatting.py', 'stats.py', 'tests/test_report.py']
probe = '''import app, json
results = []
for default in (False, True):
    app.DETAILED_REPORT = default
    for values in ([], [2, 4], [-2, 2], [1, 2, 2], [0.25]):
        for mode in (None, False, True):
            try:
                result = {'text': app.report(values) if mode is None else app.report(values, detailed=mode)}
            except Exception as exc:
                result = {'error': type(exc).__name__, 'message': str(exc)}
            results.append({'default': default, 'values': values, 'mode': mode, 'result': result})
print(json.dumps(results))
'''
outputs = {}
for name, revision in [('HEAD', 'HEAD:'), ('index', ':')]:
    with tempfile.TemporaryDirectory(prefix='batch-report-review-') as directory:
        for filename in files:
            path = Path(directory) / filename
            path.parent.mkdir(parents=True, exist_ok=True)
            path.write_bytes(subprocess.check_output(['git', 'show', revision + filename]))
        tests = subprocess.run([sys.executable, '-B', '-m', 'unittest', 'discover', '-s', 'tests'], cwd=directory, text=True, capture_output=True)
        print(f'{name} unit tests: exit {tests.returncode}\\n{tests.stdout}{tests.stderr}', flush=True)
        tests.check_returncode()
        outputs[name] = json.loads(subprocess.check_output([sys.executable, '-B', '-c', probe], cwd=directory, text=True))

for before, after in zip(outputs['HEAD'], outputs['index']):
    expected = dict(before['result'])
    if 'text' in expected:
        expected['text'] = expected['text'].replace('Items: ', 'Records: ', 1)
    assert after['result'] == expected, (before, after)
print(f\"Compared {len(outputs['index'])} scenarios: only the count label changed.\")
print('Representative candidate results:')
for row in outputs['index']:
    if row['default'] is False and row['values'] in ([], [2, 4], [1, 2, 2]):
        print(json.dumps(row))
print('Interpreter:', sys.version.split()[0])
PY"

